import{_ as a}from"./chunks/concept-diagram.Cp24n1VV.js";import{_ as e,o as l,c as r,a5 as o}from"./chunks/framework.CcrBcQWS.js";const _=JSON.parse('{"title":"개념","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/concept.md","filePath":"ko/software/concept.md","lastUpdated":1787021357000}'),i={name:"ko/software/concept.md"};function n(s,t,h,d,c,u){return l(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="개념" tabindex="-1">개념 <a class="header-anchor" href="#개념" aria-label="Permalink to &quot;개념&quot;">​</a></h1><h2 id="시스템-다이어그램" tabindex="-1">시스템 다이어그램 <a class="header-anchor" href="#시스템-다이어그램" aria-label="Permalink to &quot;시스템 다이어그램&quot;">​</a></h2><br><figure><img src="'+a+'" alt="RBQ 소프트웨어 개념 구성도"></figure><br><h2 id="sdk-개요" tabindex="-1">SDK 개요 <a class="header-anchor" href="#sdk-개요" aria-label="Permalink to &quot;SDK 개요&quot;">​</a></h2><p><strong>RBQ SDK</strong>는 개발자에게 <strong>RBQ 사족보행 로봇</strong>을 위한 유연하고 확장 가능한 인터페이스를 제공하기 위해 설계되었습니다.</p><p><strong>Low Level 제어</strong>와 <strong>High Level 명령</strong>을 모두 지원하므로, 자체 컨트롤러를 개발하거나 로봇을 기존 시스템에 통합하는 경우 모두 적합한 진입점이 있습니다.</p><h2 id="low-level-접근" tabindex="-1">Low Level 접근 <a class="header-anchor" href="#low-level-접근" aria-label="Permalink to &quot;Low Level 접근&quot;">​</a></h2><p><strong>LV0 SDK</strong>는 로봇의 센서와 액추에이터에 직접 접근할 수 있습니다.</p><p><strong>정밀한 제어</strong>와 하드웨어로부터의 <strong>실시간 피드백</strong>이 필요한 개발자를 위해 설계되었습니다.</p><h3 id="주요-기능" tabindex="-1">주요 기능: <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능:&quot;">​</a></h3><ul><li>센서 데이터 읽기: IMU, 조인트 인코더 등</li><li>조인트 레벨 명령 전송: 위치, 속도, 토크</li><li>적합한 용도: <ul><li>커스텀 컨트롤러 개발</li><li>저지연 실시간 실험</li><li>보행 제어 연구</li></ul></li></ul><h2 id="high-level-명령-인터페이스" tabindex="-1">High Level 명령 인터페이스 <a class="header-anchor" href="#high-level-명령-인터페이스" aria-label="Permalink to &quot;High Level 명령 인터페이스&quot;">​</a></h2><p><strong>LV1 SDK</strong>는 Low Level 세부 사항을 관리할 필요 없이 사전 정의된 동작과 명령을 사용하여 로봇을 제어할 수 있는 <strong>간소화된 인터페이스</strong>를 제공합니다.</p><h3 id="주요-기능-1" tabindex="-1">주요 기능: <a class="header-anchor" href="#주요-기능-1" aria-label="Permalink to &quot;주요 기능:&quot;">​</a></h3><ul><li>단일 명령으로 일반적인 모션 및 보행 동작 실행</li><li><strong>RBQ APP</strong> 명령 세트와 원활한 통합</li><li>사용 가능한 API: <ul><li>C/C++</li><li>Python</li><li>ROS2</li></ul></li><li>적합한 용도: <ul><li>애플리케이션 개발자</li><li>시스템 통합</li><li>최소한의 설정으로 빠른 프로토타이핑</li></ul></li></ul><h2 id="지원되는-통신-인터페이스" tabindex="-1">지원되는 통신 인터페이스 <a class="header-anchor" href="#지원되는-통신-인터페이스" aria-label="Permalink to &quot;지원되는 통신 인터페이스&quot;">​</a></h2><p>SDK는 사용 사례에 따라 여러 통신 프로토콜을 지원합니다:</p><table><tr><th>인터페이스</th><th>설명</th></tr><tr><td>ROS2 SDK</td><td>ROS2 생태계의 로보틱스 개발자용</td></tr><tr><td>DDS SDK</td><td>DDS를 사용한 실시간 분산 통신용</td></tr><tr><td>TCP / UDP</td><td>커스텀 도구를 위한 경량 직접 패킷 통신</td></tr></table>',20)])])}const f=e(i,[["render",n]]);export{_ as __pageData,f as default};
